function ic(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('lt-LT',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n||0);
const eur=n=>fmt(n)+' €';
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
const sum=a=>round(a.reduce((s,v)=>s+v,0));
const cats=['Darbo užmokestis','Medžiagos','Mechanizmai','Subranga','Statybvietės išlaidos','Pridėtinės išlaidos','Administracinės išlaidos'];
const months=['2026-09','2026-10','2026-11'];
const monthNames={'2026-09':'2026 m. rugsėjis','2026-10':'2026 m. spalis','2026-11':'2026 m. lapkritis'};
const subgroups=[['Darbininkai (su mokesčiais)','Inžinerinis personalas (su mokesčiais)'],['Žaliavos, gaminiai ir pristatymas','Pastoliai, klojiniai'],['Mechanizmų nuoma ir įrankiai','Kuras mechanizmams'],['ŠVOK ir vandentiekis','Grindų įrengimas','Tinkavimo darbai','Silpnos srovės'],['Bio tualetai, vagonėliai, tvoros','Elektra, vanduo','Kuras automobiliams','Sąvartyno paslaugos','Objekto apsauga','Mažaverčio pirkimai'],['Patalpų nuoma','Draudimai ir laidavimo raštai','Ryšių paslaugos','Transporto nuoma','Remontas ir kitos išlaidos','Orgtechnika','Valymas'],['Administracinės išlaidos']];
function seed(){
 const defs=[['p1','VRS-026','Šiaulių kultūros centras','Šiauliai','Projekto vadovas A','Vykdomas',[777650.86,1522159.36,100010.72,678488.62,7800,24700,97088.70],[97631.35,390083.70,8834.13,63000,13834.55,6505.45,15000],200174.47],['p2','VRS-031','Administracinio pastato rekonstrukcija','Klaipėda','Projekto vadovas B','Vykdomas',[240000,520000,65000,420000,38000,42000,45000],[143000,286000,31000,187000,22000,16800,19000],160000],['p3','VRS-034','Sandėliavimo paskirties pastatas','Kaunas','Projekto vadovas A','Planuojamas',[190000,480000,55000,330000,24000,28000,35000],[0,0,0,0,0,0,0],138000]];
 const state={version:3,projects:[],docs:[],history:[],sync:null,batch:false,logs:[]};
 defs.forEach((d,pi)=>{let budgets=d[6], plans={};months.forEach((m,mi)=>{plans[m]={values:pi===0?(mi===0?[15018.54,50000,500,25000,1550,580,3500]:mi===1?[17018.54,42000,1800,45000,3000,1300,3500]:[18000,60000,2200,55000,3200,1500,4000]):budgets.map(v=>round(v*(pi===1?(.06+mi*.01):0))),revenue:pi===0?[120000,150000,180000][mi]:pi===1?[140000,165000,180000][mi]:0,note:''}});
 state.projects.push({id:d[0],code:d[1],name:d[2],city:d[3],manager:d[4],status:d[5],start:'2026-01-12',end:'2027-09-06',budgets:budgets.slice(),initial:sum(budgets),contract:round(sum(budgets)+d[8]),base:d[7],baseRevenue:pi===0?730000:pi===1?840000:0,plans,openingStocks:pi===0?[63932.40,2500]:pi===1?[42000,1800]:[0,0],stocks:Object.fromEntries(months.map((m,i)=>[m,pi===0?[61432.40-i*2000,2100-i*150]:pi===1?[38000-i*3000,1600-i*100]:[0,0]])),advance:pi===0?80240:pi===1?35000:0,revenues:{},paidAdvances:{}});
 if(pi===2)return;
 months.forEach((m,mi)=>{
 const v=pi===0?[[15018.54,50000,867.19,6174.05,9643.30,997.40,3500],[18021.22,43840,2150,48500,3250,1450,3500],[18640,61500,2370,52000,2900,1300,4000]][mi]:[15500+mi*2300,42000+mi*2000,2200,38000+mi*5000,2800,1550,3200];
 v.forEach((amount,c)=>{
 const details=c===0?[{amount:round(amount*.60),name:'Darbininkai (su mokesčiais)'},{amount:round(amount-round(amount*.6)),name:'Inžinerinis personalas (su mokesčiais)'}]:c===3&&pi===0&&mi===0?[{amount:250,name:'Grindų įrengimas'},{amount:5924.05,name:'Silpnos srovės'}]:c===4&&pi===0&&mi===0?[{amount:1036,name:subgroups[4][0]},{amount:7267.30,name:subgroups[4][1]},{amount:400,name:subgroups[4][2]},{amount:940,name:subgroups[4][3]}]:[{amount,name:subgroups[c][0]}];
 details.forEach((x,j)=>state.docs.push({id:`D-${pi}-${mi}-${c}-${j}`,project:d[0],date:m+`-${String(7+c*2).padStart(2,'0')}`,number:c===0?'DU-'+m+'-'+(j+1):`SF-${2600+pi*200+mi*50+c*3+j}`,supplier:c===0?'Darbo užmokesčio suvestinė':c===3?['Subrangovas A','Subrangovas B'][j%2]:['','Medžiagų tiekėjas','Mechanizmų nuoma','','Statybvietės paslaugos','Paslaugų tiekėjas','Administracija'][c],category:c,sub:x.name,amount:x.amount,source:'HANSA'}));
 });
 const p=state.projects[pi];p.revenues[m]=pi===0?[117500,142500,173800][mi]:[136000,159000,178000][mi];p.paidAdvances[m]=mi===2&&pi===0?5000:0;
 });
 });return state;
}
let db;try{db=JSON.parse(localStorage.getItem('versina-demo-v3'));if(db?.version!==3)db=seed()}catch{db=seed()}
let view='object',pid='p1',tab='control',month='2026-11',filter='',doccat='all',objstatus='all',role='pv';
function persist(){localStorage.setItem('versina-demo-v3',JSON.stringify(db))}
const project=()=>db.projects.find(p=>p.id===pid)||db.projects[0];
const writable=()=>role==='pv';
function invoices(p,m=month,c=null){return db.docs.filter(d=>d.project===p.id&&d.date.slice(0,7)===m&&(c===null||d.category===c))}
function actual(p,c,m=month){return sum(invoices(p,m,c).map(d=>d.amount))}
function cumulative(p,c,m=month){return round(p.base[c]+sum(db.docs.filter(d=>d.project===p.id&&d.category===c&&d.date.slice(0,7)<=m).map(d=>d.amount)))}
function stats(p){let b=sum(p.budgets),a=sum(cats.map((_,c)=>cumulative(p,c))),f=sum(cats.map((_,c)=>actual(p,c))),pl=sum(p.plans[month].values);return {b,a,f,pl,left:round(b-a),profit:round(p.contract-b)}}
function stocks(p,m=month){return p.stocks[m]||[0,0]}
function prevStocks(p,m=month){let i=months.indexOf(m);return i>0?stocks(p,months[i-1]):p.openingStocks}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function nav(v){view=v;filter='';doccat='all';render();window.scrollTo(0,0)}
function openProject(id,t='control'){pid=id;tab=t;view='object';filter='';render();window.scrollTo(0,0)}
function badge(p){return `<span class="badge ${p.status==='Vykdomas'?'green':p.status==='Užbaigtas'?'purple':''}">${esc(p.status)}</span>`}
function selectProject(){return `<div class="toolfield"><label for="objectSelect">Objektas</label><select id="objectSelect" onchange="pid=this.value;render()">${db.projects.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${esc(p.code+' · '+p.name)}</option>`).join('')}</select></div>`}
function period(){return `<div class="toolfield"><label for="periodSelect">Laikotarpis</label><select id="periodSelect" onchange="month=this.value;render()">${months.map(m=>`<option value="${m}" ${month===m?'selected':''}>${monthNames[m]}</option>`).join('')}</select></div>`}
function syncText(){return db.sync?'Atnaujinta '+db.sync:'Demo duomenys · HANSA'}
function toolbar(withProject=false){return `<div class="toolbar">${withProject?selectProject():''}${period()}<div class="sync">${ic('clock')}${esc(syncText())}</div></div>`}
function metric(label,value,note='',cls=''){return `<div class="metric ${cls}"><label>${label}</label><div class="value">${value}</div>${note?`<div class="sub">${note}</div>`:''}</div>`}
function reportLink(className='navitem'){
 const raw=window.VERSINA_CONFIG?.reportUrl?.trim();
 if(!raw)return '';
 try{const u=new URL(raw,document.baseURI);if(!['https:','http:'].includes(u.protocol))return '';return `<a class="${className}" aria-label="Ataskaita" title="Atidaryti ataskaitą" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer" style="text-decoration:none">${ic('chart')}<span>Ataskaita</span></a>`}catch{return ''}
}
function render(){
 const active=view==='object'?'objects':view;
 $('#app').innerHTML=`<header class="topbar"><button class="menubtn icon" aria-label="Meniu" onclick="$('.shell').classList.toggle('menuopen')">${ic('menu')}</button>${ic('grid')}<span class="appname">Power Apps</span><span class="divider"></span><span class="appname">Objektų biudžetų kontrolė</span><span class="demo">DEMONSTRACIJA</span><div class="topright">${reportLink('top-report-link')}<button class="icon" aria-label="Kaip naudotis demo" onclick="showHelp()">${ic('help')}</button><span style="font-size:.8rem">${role==='pv'?'Projekto vadovas':'Įmonės vadovas'}</span><button class="avatar" aria-label="Keisti demo vaidmenį" onclick="showRole()">${role==='pv'?'PV':'ĮV'}</button></div></header><div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark"><span></span><span></span><span></span></div><span>VERSINA</span></div><div class="navlabel">Darbo erdvė</div>${[['overview','grid','Apžvalga'],['objects','objects','Objektai'],['planning','calendar','Mėnesio planavimas']].map(n=>`<button class="navitem ${active===n[0]?'active':''}" onclick="nav('${n[0]}')">${ic(n[1])}<span>${n[2]}</span>${n[0]==='objects'?`<span class="navcount">${db.projects.length}</span>`:''}</button>`).join('')}${reportLink()}<div class="navlabel" style="margin-top:27px">Duomenys</div><button class="navitem ${active==='sources'?'active':''}" onclick="nav('sources')">${ic('source')}<span>Duomenų šaltiniai</span></button><div class="sidebarfoot"><strong>Demonstracinė aplinka</strong>Pavyzdiniai objektai ir sumos.<br>Pakeitimai saugomi šioje naršyklėje.</div></aside><main class="main">${view==='object'?objectPage():view==='objects'?objectsPage():view==='planning'?planningPage():view==='sources'?sourcesPage():overviewPage()}<footer class="pagefoot"><span>VERSINA · Statybos objektų finansų valdymas</span><span>Visos sumos eurais, be PVM · Demonstraciniai duomenys</span></footer></main></div>`;
}
function objectPage(){let p=project(),s=stats(p);return `<div class="breadcrumb"><button onclick="nav('objects')">Objektai</button><span>/</span><span>${esc(p.code)}</span></div><div class="heading"><div><h1>${esc(p.name)}</h1><div class="projectmeta">${badge(p)}<span>${esc(p.code)}</span><span>·</span><span>${esc(p.city)}</span><span>·</span><span>${esc(p.manager)}</span></div></div><div class="headingactions">${writable()?`<button onclick="showBudget()">${ic('calendar')}Biudžeto planas</button><button onclick="editProject('${p.id}')">${ic('edit')}Objekto kortelė</button><button class="primary" onclick="showTransfer()">${ic('swap')}Perskirstyti biudžetą</button>`:`<span class="viewonly">${ic('lock')} Peržiūros režimas</span>`}</div></div>${toolbar()}<div class="cards">${metric('Objekto biudžetas',eur(s.b),'Sutartis: '+eur(p.contract),'featured')}${metric('Faktas nuo objekto pradžios',eur(s.a),'Iki pasirinkto mėnesio pabaigos')}${metric('Biudžeto likutis',eur(s.left),`<span class="${s.left<0?'textred':'textgreen'}">${fmt(s.a/s.b*100)} % biudžeto panaudota</span>`)}${metric('Planuojamas pelnas',eur(s.profit),fmt(s.profit/p.contract*100)+' % sutarties vertės')}</div><div class="tabs" role="tablist">${[['control','Biudžeto kontrolė'],['monthly','Mėnesio ataskaita'],['documents','Sąnaudų dokumentai'],['inventory','Medžiagų likučiai'],['history','Perskirstymų istorija']].map(t=>`<button role="tab" aria-selected="${tab===t[0]}" class="tab ${tab===t[0]?'active':''}" onclick="tab='${t[0]}';filter='';doccat='all';render()">${t[1]}</button>`).join('')}</div>${tab==='control'?controlPanel():tab==='monthly'?monthlyReport():tab==='documents'?documentsPanel():tab==='inventory'?inventoryPanel():historyPanel()}`}
function controlPanel(){const p=project(),s=stats(p);return `<section class="panel"><div class="panelhead"><div><h2>Biudžetas ir faktinės sąnaudos</h2><p>Pasirinkite sąnaudų grupę ir peržiūrėkite jos detales.</p></div><button onclick="exportBudget()">${ic('download')}Eksportuoti</button></div><div class="tablewrap"><table><thead><tr><th>Sąnaudų grupė</th><th class="num">Biudžetas</th><th class="num">${monthNames[month].split(' ').slice(2).join(' ')} · faktas</th><th class="num">Faktas nuo pradžios</th><th class="num">Likutis</th><th class="num">Panaudota</th></tr></thead><tbody>${cats.map((n,c)=>{let a=cumulative(p,c),f=actual(p,c),left=round(p.budgets[c]-a),pct=p.budgets[c]?a/p.budgets[c]*100:0;return `<tr class="clickrow" tabindex="0" role="button" aria-label="${n}: detalizacija" onclick="showCategory(${c})" onkeydown="if(event.key==='Enter')showCategory(${c})"><td><div class="groupname"><span class="n">${c+1}.</span>${n}</div>${left<0?'<div class="rownote textred">Viršytas grupės biudžetas</div>':''}</td><td class="num">${fmt(p.budgets[c])}</td><td class="num">${fmt(f)}</td><td class="num">${fmt(a)}</td><td class="num ${left<0?'textred':''}">${fmt(left)}</td><td class="num"><div class="progressrow"><div class="track"><i class="${left<0?'red':''}" style="width:${Math.min(pct,100)}%"></i></div><span class="percent ${left<0?'textred':''}">${fmt(pct)} %</span></div></td></tr>`}).join('')}<tr class="total"><td>Iš viso</td><td class="num">${fmt(s.b)}</td><td class="num">${fmt(s.f)}</td><td class="num">${fmt(s.a)}</td><td class="num">${fmt(s.left)}</td><td></td></tr></tbody></table></div><div class="panelnote">${ic('info')}Faktinės sąnaudos ir dokumentai gaunami iš HANSA. Biudžeto likutis = biudžetas − faktas nuo objekto pradžios.</div></section><div class="bottomgrid"><section class="panel"><div class="panelhead"><div><h2>Mėnesio planas ir faktas</h2><p>Sąnaudos pagal mėnesį</p></div><div class="legend"><span><i class="swatch"></i>Planas</span><span><i class="swatch actual"></i>Faktas</span></div></div>${chart(p)}</section><section class="panel"><div class="panelhead"><div><h2>Reikia dėmesio</h2><p>Pasirinkto mėnesio biudžeto kontrolė</p></div></div>${alerts(p)}</section></div>`}
function chart(p){let vals=months.map(m=>[sum(p.plans[m].values),sum(cats.map((_,c)=>actual(p,c,m)))]),max=Math.max(...vals.flat(),1)*1.12;return `<div class="chart">${vals.map((v,i)=>`<div class="chartcol"><div class="chartbar" style="height:${v[0]/max*100}%" title="Planas: ${eur(v[0])}"></div><div class="chartbar actual" style="height:${v[1]/max*100}%" title="Faktas: ${eur(v[1])}"></div><label>${['Rugsėjis','Spalis','Lapkritis'][i]}</label></div>`).join('')}</div>`}
function alerts(p){let a=cats.map((n,c)=>({n,c,left:round(p.budgets[c]-cumulative(p,c)),delta:round(actual(p,c)-p.plans[month].values[c])})).filter(v=>v.left<0||v.delta>0).sort((a,b)=>(a.left<0?-1:0)-(b.left<0?-1:0)||Math.max(-b.left,b.delta)-Math.max(-a.left,a.delta)).slice(0,3);return a.length?a.map(v=>`<div class="notice">${ic('warn')}<div><strong>${v.n}</strong><small>${v.left<0?'Biudžetas viršytas '+eur(-v.left):'Mėnesio planas viršytas '+eur(v.delta)}</small><button class="linkbutton" onclick="showCategory(${v.c})">Peržiūrėti detales</button></div></div>`).join(''):`<div class="notice">${ic('check')}<div><strong>Biudžetas kontroliuojamas</strong><small>Grupių ir mėnesio plano viršijimų nėra.</small></div></div>`}
function objectsPage(){let list=db.projects.filter(p=>(objstatus==='all'||p.status===objstatus)&&[p.name,p.code,p.city,p.manager].some(v=>v.toLowerCase().includes(filter.toLowerCase())));return `<div class="breadcrumb">Darbo erdvė / Objektai</div><div class="heading"><div><h1>Statybos objektai</h1><p>Objektų biudžetai, mėnesio planai ir faktinės sąnaudos vienoje vietoje.</p></div>${writable()?`<button class="primary" onclick="editProject()">${ic('plus')}Naujas objektas</button>`:''}</div><div class="toolbar"><div class="search">${ic('search')}<input placeholder="Ieškoti objekto, miesto..." value="${esc(filter)}" oninput="setSearch(this,'objects')" aria-label="Ieškoti objektų"></div><select aria-label="Objekto būsena" onchange="objstatus=this.value;render()"><option value="all">Visos būsenos</option>${['Vykdomas','Planuojamas','Užbaigtas'].map(s=>`<option ${s===objstatus?'selected':''}>${s}</option>`).join('')}</select><span class="sync">${list.length} objektai</span></div><div class="objectgrid">${list.map(p=>{let s=stats(p);return `<article class="objectcard" tabindex="0" role="button" aria-label="Atidaryti ${esc(p.name)}" onclick="openProject('${p.id}')" onkeydown="if(event.key==='Enter')openProject('${p.id}')"><div class="objectart"><div class="building"></div><div class="building"></div></div><div class="objectbody">${badge(p)}<h2>${esc(p.name)}</h2><p>${esc(p.code+' · '+p.city)}</p><div class="objectstats"><div><span>Biudžetas</span><strong>${eur(s.b)}</strong></div><div><span>Panaudota iki ${month.slice(5)}</span><strong>${eur(s.a)}</strong></div></div><div class="track" style="width:100%;margin-top:20px"><i style="width:${Math.min(s.a/(s.b||1)*100,100)}%"></i></div></div><div class="objectfooter"><span>${esc(p.manager)}</span><span class="textpurple">Atidaryti</span></div></article>`}).join('')||'<div class="empty">Objektų pagal paiešką nerasta.</div>'}</div>`}
function setSearch(el,type){let start=el.selectionStart;filter=el.value;render();let n=$(type==='objects'?'.toolbar .search input':'.filterbar .search input');n.focus();n.setSelectionRange(start,start)}
function overviewPage(){const all=db.projects.map(stats),budget=sum(all.map(s=>s.b)),used=sum(all.map(s=>s.a));return `<div class="breadcrumb">Darbo erdvė / Apžvalga</div><div class="heading"><div><h1>Objektų finansinė apžvalga</h1><p>Biudžeto kontrolė ir svarbiausi nukrypimai.</p></div></div>${toolbar()}<div class="cards">${metric('Statybos objektai',db.projects.length,db.projects.filter(p=>p.status==='Vykdomas').length+' vykdomi objektai','featured')}${metric('Bendras biudžetas',eur(budget),'Visų objektų biudžetų suma')}${metric('Faktas nuo objektų pradžios',eur(used),'Iki pasirinkto mėnesio pabaigos')}${metric('Bendras likutis',eur(budget-used),'Pagal HANSA sąnaudų duomenis')}</div>${portfolioTable()}<div class="bottomgrid"><section class="panel"><div class="panelhead"><div><h2>Kontrolės pranešimai</h2><p>Objektai ir sąnaudų grupės</p></div></div>${db.projects.filter(p=>p.status==='Vykdomas').map(p=>`<div style="padding:8px 22px;font-size:.85rem;font-weight:600"><button class="linkbutton" onclick="openProject('${p.id}')">${esc(p.name)}</button></div>${alerts(p)}`).join('')}</section><section class="panel"><div class="panelhead"><div><h2>Duomenų šaltiniai</h2><p>Planas ir faktas turi atskiras atsakomybes.</p></div></div><div class="notice">${ic('calendar')}<div><strong>Power Apps</strong><small>Objektų registras ir biudžetų planavimas.</small></div></div><div class="notice">${ic('source')}<div><strong>HANSA</strong><small>Faktinės sąnaudos, aktavimas ir likučiai.</small></div></div></section></div>`}
function portfolioTable(){return `<section class="panel"><div class="panelhead"><div><h2>Objektų biudžetų vykdymas</h2><p>Pasirinkite objektą ir peržiūrėkite biudžeto eilutes.</p></div></div><div class="tablewrap"><table><thead><tr><th>Objektas</th><th>Būsena</th><th class="num">Biudžetas</th><th class="num">Faktas nuo pradžios</th><th class="num">Likutis</th><th class="num">Mėnesio rezultatas</th></tr></thead><tbody>${db.projects.map(p=>{let s=stats(p);return `<tr class="clickrow" tabindex="0" onclick="openProject('${p.id}')" onkeydown="if(event.key==='Enter')openProject('${p.id}')"><td><strong>${esc(p.name)}</strong><div class="rownote" style="margin-left:0">${esc(p.code)}</div></td><td>${badge(p)}</td><td class="num">${fmt(s.b)}</td><td class="num">${fmt(s.a)}</td><td class="num ${s.left<0?'textred':''}">${fmt(s.left)}</td><td class="num">${fmt((p.revenues[month]||0)-s.f)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function planningPage(){let p=project(),pl=p.plans[month],s=stats(p);return `<div class="breadcrumb">Darbo erdvė / Mėnesio planavimas</div><div class="heading"><div><h1>Mėnesio planavimas</h1><p>Suplanuokite aktavimą ir išlaidas pagal objekto biudžeto eilutes.</p></div><div class="headingactions"><button onclick="openProject(pid,'monthly')">${ic('file')}Mėnesio ataskaita</button>${writable()?`<button class="primary" onclick="savePlan()">${ic('save')}Išsaugoti planą</button>`:''}</div></div>${toolbar(true)}<div class="callout">${ic('info')}Bendras objekto biudžetas: <strong>${eur(s.b)}</strong>. Mėnesio planas nekeičia bendro biudžeto. Faktas gaunamas iš HANSA.</div><section class="panel"><div class="panelhead"><div><h2>${esc(p.name)}</h2><p>${monthNames[month]} · Mėnesio planas ir faktas</p></div><span class="badge purple">${writable()?'Redaguojamas planas':'Tik peržiūra'}</span></div><div class="tablewrap"><table><thead><tr><th>Sąnaudų grupė</th><th class="num">Objekto biudžetas</th><th class="num">Mėnesio planas</th><th class="num">Mėnesio faktas</th><th class="num">Faktas − planas</th></tr></thead><tbody>${cats.map((n,c)=>`<tr><td>${n}${writable()?`<div style="margin-top:5px"><button class="linkbutton" style="font-size:.75rem" onclick="showPlanDetails(${c},true)">Planuoti pogrupius</button></div>`:''}</td><td class="num">${fmt(p.budgets[c])}</td><td class="num"><input aria-label="${n} mėnesio planas" class="editcell" id="plan-${c}" type="number" min="0" step="0.01" value="${pl.values[c]}" ${writable()?'':'disabled'} oninput="planPreview()"></td><td class="num">${fmt(actual(p,c))}</td><td class="num ${actual(p,c)>pl.values[c]?'textred':''}">${fmt(actual(p,c)-pl.values[c])}</td></tr>`).join('')}<tr class="total"><td>Iš viso sąnaudų</td><td class="num">${fmt(s.b)}</td><td class="num" id="plan-total">${fmt(s.pl)}</td><td class="num">${fmt(s.f)}</td><td class="num">${fmt(s.f-s.pl)}</td></tr></tbody></table></div><div class="sourcebody" style="padding-top:22px"><div class="formgrid"><div class="formfield"><label for="plan-revenue">Planuojama aktavimo suma (€)</label><input type="number" id="plan-revenue" min="0" step="0.01" value="${pl.revenue}" oninput="planPreview()" ${writable()?'':'disabled'}></div><div class="formfield"><label>Planuojamas mėnesio rezultatas</label><strong id="plan-result" style="padding:10px 0">${eur(pl.revenue-s.pl)}</strong></div><div class="formfield full"><label for="plan-note">Plano komentaras</label><textarea id="plan-note" placeholder="Paaiškinimai apie mėnesio planą..." ${writable()?'':'disabled'}>${esc(pl.note)}</textarea></div></div></div></section>`}
function planPreview(){let vals=cats.map((_,c)=>Number($('#plan-'+c).value)||0),t=sum(vals);$('#plan-total').textContent=fmt(t);$('#plan-result').textContent=eur((Number($('#plan-revenue').value)||0)-t)}
function savePlan(){if(!writable())return;let inputs=[...document.querySelectorAll('[id^="plan-"][type="number"]')];if(inputs.some(i=>!i.checkValidity()||i.value===''))return toast('Įveskite neneigiamas plano sumas.');let p=project();let details=cats.map((_,c)=>planParts(p,c));let values=cats.map((_,c)=>round(Number($('#plan-'+c).value)));p.plans[month]={values,revenue:round(Number($('#plan-revenue').value)),note:$('#plan-note').value,details:details.map((parts,c)=>allocate(values[c],parts))};persist();render();toast('Mėnesio planas išsaugotas.')}
function monthlyReport(){let p=project(),s=stats(p),rev=p.revenues[month]||0,plan=p.plans[month],prev=round(sum(cats.map((_,c)=>cumulative(p,c)))-s.f),revTotal=round(p.baseRevenue+sum(months.filter(m=>m<=month).map(m=>p.revenues[m]||0))),stock=sum(stocks(p));let summary=[['Aktuojama suma ataskaitinį mėnesį',plan.revenue,rev,'Iš HANSA pardavimo dokumentų'],['Visos sąnaudos ataskaitinį mėnesį',s.pl,s.f,'Iš HANSA sąnaudų dokumentų'],['Mėnesio rezultatas',plan.revenue-s.pl,rev-s.f,'Aktavimas − mėnesio sąnaudos'],['Rezultatas nuo objekto pradžios',null,revTotal-s.a,'Sukauptas aktavimas − sukauptos sąnaudos'],['Medžiagų ir mažaverčio likučiai',null,stock,'Atskirai rodomas turto likutis'],['Planuojamas objekto pelnas',s.profit,s.profit,'Iš bendro biudžeto'],['Avansų nepadengtas likutis',null,p.advance,'Iš HANSA'],['Per mėnesį išmokėti avansai',null,p.paidAdvances[month]||0,'Iš HANSA']];return `<section class="panel"><div class="panelhead"><div><h2>Mėnesio finansinė ataskaita</h2><p>${monthNames[month]} · ${esc(p.code)} · ${esc(p.name)}</p></div><div class="inlineactions"><button onclick="exportMonthly()">${ic('download')}CSV</button><button onclick="window.print()">${ic('print')}Spausdinti</button></div></div><div class="tablewrap"><table><thead><tr><th>Rodiklis</th><th class="num">Planas (€)</th><th class="num">Faktas (€)</th><th>Paaiškinimas</th></tr></thead><tbody>${summary.map((r,i)=>`<tr class="${i===2?'reportgroup':''}"><td>${r[0]}</td><td class="num">${r[1]===null?'—':fmt(r[1])}</td><td class="num ${i===2&&r[2]<0?'textred':''}">${fmt(r[2])}</td><td style="color:var(--muted);font-size:.75rem">${r[3]}</td></tr>`).join('')}</tbody></table></div><div class="panelhead" style="padding-bottom:15px"><div><h2>Ataskaitinio mėnesio sąnaudų detalizacija</h2><p>Biudžeto eilutės išlaiko pateiktų lentelių struktūrą.</p></div></div><div class="tablewrap"><table><thead><tr><th>Aprašymas</th><th class="num">Planas (€)</th><th class="num">Faktas (€)</th><th>Duomenų šaltinis</th></tr></thead><tbody>${cats.map((n,c)=>`<tr class="reportgroup"><td>${c+1}. ${n} · biudžetas</td><td class="num">${fmt(p.budgets[c])}</td><td class="num">${fmt(p.budgets[c])}</td><td>Power Apps</td></tr><tr class="subrow"><td>Panaudota iki ataskaitinio mėnesio</td><td class="num">—</td><td class="num">${fmt(cumulative(p,c)-actual(p,c))}</td><td>HANSA</td></tr><tr class="subrow"><td>Panaudota įskaitant ataskaitinį mėnesį</td><td class="num">—</td><td class="num">${fmt(cumulative(p,c))}</td><td>HANSA</td></tr><tr class="subrow"><td>Biudžeto likutis</td><td class="num">—</td><td class="num ${p.budgets[c]<cumulative(p,c)?'textred':''}">${fmt(p.budgets[c]-cumulative(p,c))}</td><td>Biudžetas − sukauptas faktas</td></tr><tr><td><button class="linkbutton" onclick="showCategory(${c})">${n} ataskaitinį mėnesį</button></td><td class="num">${fmt(plan.values[c])}</td><td class="num">${fmt(actual(p,c))}</td><td>HANSA</td></tr>${subgroups[c].map((sub,si)=>`<tr class="subrow"><td>${esc(sub)}</td><td class="num">${fmt(planParts(p,c)[si])}</td><td class="num">${fmt(sum(invoices(p,month,c).filter(d=>d.sub===sub).map(d=>d.amount)))}</td><td>${c===0?'DU suvestinė':'Sąnaudų dokumentai'}</td></tr>`).join('')}`).join('')}</tbody></table></div><div class="panelnote">${ic('info')}Demo rezultate sąnaudos rodomos pagal HANSA dokumentus. Sandėlio likučiai pateikiami atskirai ir antrą kartą į sąnaudas neįtraukiami. Detali rezultatų skaičiavimo tvarka derinama diegimo metu.</div></section>`}
function documentsPanel(){let p=project(),docs=invoices(p).filter(d=>(doccat==='all'||d.category===Number(doccat))&&[d.supplier,d.number,d.sub].some(v=>v.toLowerCase().includes(filter.toLowerCase())));return `<section class="panel"><div class="panelhead"><div><h2>Faktinių sąnaudų dokumentai</h2><p>${docs.length} dokumentai · Duomenų šaltinis: HANSA · Tik peržiūra</p></div><button onclick="exportDocs()">${ic('download')}Eksportuoti</button></div><div class="filterbar"><div class="search">${ic('search')}<input aria-label="Ieškoti dokumentų" placeholder="Tiekėjas, dokumentas, sąnaudos..." value="${esc(filter)}" oninput="setSearch(this,'docs')"></div><select aria-label="Sąnaudų kategorija" onchange="doccat=this.value;render()"><option value="all">Visos sąnaudų grupės</option>${cats.map((c,i)=>`<option value="${i}" ${doccat==i?'selected':''}>${c}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>Data / dokumentas</th><th>Tiekėjas / šaltinis</th><th>Sąnaudų grupė</th><th>Detalizacija</th><th class="num">Suma (€)</th></tr></thead><tbody>${docs.map(d=>`<tr class="clickrow" tabindex="0" onclick="showDocument('${d.id}')" onkeydown="if(event.key==='Enter')showDocument('${d.id}')"><td><strong>${esc(d.number)}</strong><div class="rownote" style="margin-left:0">${d.date}</div></td><td>${esc(d.supplier)}</td><td>${cats[d.category]}</td><td style="font-size:.8rem;color:var(--muted)">${esc(d.sub)}</td><td class="num">${fmt(d.amount)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Dokumentų pagal filtrą nerasta.</td></tr>'}<tr class="total"><td colspan="4">Atrinktų dokumentų suma</td><td class="num">${fmt(sum(docs.map(d=>d.amount)))}</td></tr></tbody></table></div><div class="panelnote">${ic('lock')}Sąskaitos ir faktinės sumos tvarkomos HANSA sistemoje. Šioje aplikacijoje jos neredaguojamos.</div></section>`}
function inventoryPanel(){let p=project(),open=prevStocks(p),close=stocks(p);return `<section class="panel"><div class="panelhead"><div><h2>Medžiagų ir mažaverčio likučiai</h2><p>Likučių vertė ataskaitinio laikotarpio pabaigoje · HANSA</p></div><button onclick="nav('sources')">${ic('source')}Duomenų šaltinis</button></div><div class="tablewrap"><table><thead><tr><th>Likučių grupė</th><th class="num">Mėnesio pradžioje (€)</th><th class="num">Mėnesio pabaigoje (€)</th><th class="num">Pokytis (€)</th></tr></thead><tbody>${['Medžiagų likučiai','Mažaverčio likučiai'].map((n,i)=>`<tr><td><strong>${n}</strong><div class="rownote" style="margin-left:0">${i?'Įrankiai ir mažavertis inventorius':'Žaliavos, gaminiai ir kitos medžiagos'}</div></td><td class="num">${fmt(open[i])}</td><td class="num">${fmt(close[i])}</td><td class="num">${fmt(close[i]-open[i])}</td></tr>`).join('')}<tr class="total"><td>Iš viso</td><td class="num">${fmt(sum(open))}</td><td class="num">${fmt(sum(close))}</td><td class="num">${fmt(sum(close)-sum(open))}</td></tr></tbody></table></div><div class="panelnote">${ic('info')}Sandėlio likučiai pateikiami atskirai nuo pirkimų sąnaudų. Nurašymų ir likučių duomenų šaltinis numatytas HANSA.</div></section>`}
function historyPanel(){let list=db.history.filter(h=>h.project===pid);return `<section class="panel"><div class="panelhead"><div><h2>Biudžeto perskirstymų istorija</h2><p>Bendra biudžeto suma išlaikoma. Kiekvienas perkėlimas turi priežastį.</p></div>${writable()?`<button class="primary" onclick="showTransfer()">${ic('swap')}Naujas perskirstymas</button>`:''}</div>${list.length?list.map(h=>`<div class="historyitem"><div class="historytop"><strong>${cats[h.from]} → ${cats[h.to]}</strong><strong class="textpurple">${eur(h.amount)}</strong></div><p>${esc(h.reason)}</p><p>${esc(h.time)} · Projekto vadovas · Bendra biudžeto suma nepasikeitė</p></div>`).join(''):'<div class="empty">Perskirstymų dar nėra. Pavyzdžiui, dalį darbo užmokesčio biudžeto galima perkelti į subrangą.</div>'}</section>`}
function sourcesPage(){return `<div class="breadcrumb">Duomenys / Duomenų šaltiniai</div><div class="heading"><div><h1>Duomenų šaltiniai</h1><p>Biudžeto planavimas ir apskaitos faktas sujungiami pagal objekto kodą bei sąnaudų grupę.</p></div><button class="primary" onclick="showSync()">${ic('refresh')}Atnaujinti demo duomenis</button></div><div class="callout">${ic('info')}Demonstracinė aplinka. Ryšys su tikra HANSA sistema nesukurtas. Atnaujinimas įkelia pavyzdinius dokumentus, kad būtų galima patikrinti plano ir fakto palyginimą.</div><div class="sourcegrid"><section class="panel"><div class="panelhead"><div><h2>HANSA</h2><p>Faktiniai apskaitos duomenys</p></div><span class="badge purple">Demonstracinis šaltinis</span></div><div class="sourcebody"><div class="kv"><span>Objekto susiejimas</span><strong>Objekto kodas (pvz., VRS-026)</strong></div><div class="kv"><span>Sąnaudų susiejimas</span><strong>Sąnaudų kategorijos kodas</strong></div><div class="kv"><span>Dokumentų įrašai</span><strong>${db.docs.length}</strong></div><div class="kv"><span>Paskutinis demo atnaujinimas</span><strong>${db.sync||'Pradiniai pavyzdiniai duomenys'}</strong></div><div class="kv"><span>Faktinių duomenų redagavimas</span><strong>HANSA sistemoje</strong></div><div class="kv"><span>Numatoma atnaujinimo eiga</span><strong>Periodiškai pagal suderintą grafiką</strong></div><p class="statusmsg">Gamybinio ryšio būdas ir atnaujinimo dažnis tikslinami pagal HANSA suteikiamas sąsajas.</p></div></section><section class="panel"><div class="panelhead"><div><h2>Power Apps ir HANSA</h2><p>Duomenų naudojimas</p></div></div><div class="notice">${ic('objects')}<div><strong>Power Apps</strong><small>Objektai, bendri biudžetai, mėnesio planai ir perskirstymai.</small></div></div><div class="notice">${ic('file')}<div><strong>HANSA duomenų peržiūra</strong><small>Sąnaudų dokumentai, aktavimas, avansai, likučiai.</small></div></div></section></div><section class="panel"><div class="panelhead"><div><h2>Sąnaudų kategorijų susiejimas</h2><p>Pavyzdiniai kodai. Tikrieji HANSA apskaitos kodai suderinami diegimo metu.</p></div></div><div class="tablewrap"><table><thead><tr><th>HANSA grupės kodas</th><th>Biudžeto eilutė</th><th>Naudojami duomenys</th></tr></thead><tbody>${cats.map((n,c)=>`<tr><td><span class="badge">S${String(c+1).padStart(2,'0')}</span></td><td>${n}</td><td style="color:var(--muted)">${c===0?'DU suvestinės':c===3?'Subrangos sąskaitos ir aktai':'Sąnaudų dokumentai'}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panelhead"><div><h2>Atnaujinimų istorija</h2><p>Demo dokumentai nekartojami pagal unikalų dokumento ID.</p></div></div>${db.logs.length?db.logs.map(l=>`<div class="historyitem"><div class="historytop"><strong>${l.count} dokumentai pridėti</strong><span class="badge green">Atnaujinta</span></div><p>${esc(l.time)} · Pavyzdinių duomenų paketas</p></div>`).join(''):'<div class="empty">Demo atnaujinimų dar nėra.</div>'}</section><button class="flat" onclick="resetDemo()">Atkurti pradinius demo duomenis</button>`}
function modal(title,body,footer=''){let m=$('#modal');m.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="icon flat" onclick="closeModal()" aria-label="Uždaryti">${ic('close')}</button></div><div class="modalbody">${body}<div id="modalerror" class="modalerror" role="alert"></div></div><div class="modalfoot"><button onclick="closeModal()">Uždaryti</button>${footer}</div>`;m.showModal()}
function closeModal(){$('#modal').close()}
function error(msg){$('#modalerror').textContent=msg}
function showHelp(){modal('Kaip pristatyti demo',`<p>Ši demonstracija skirta „Versina“ statybos objektų biudžeto kontrolei. Visi objektai, dokumentai ir sumos yra pavyzdiniai.</p><div class="notice">${ic('objects')}<div><strong>1. Pasirinkite objektą</strong><small>Peržiūrėkite bendrą biudžetą ir atverkite sąnaudų grupę.</small></div></div><div class="notice">${ic('calendar')}<div><strong>2. Suplanuokite mėnesį</strong><small>Keiskite išlaidų planą ir aktavimo sumą, išsaugokite, peržiūrėkite mėnesio ataskaitą.</small></div></div><div class="notice">${ic('swap')}<div><strong>3. Perskirstykite biudžetą</strong><small>Perkelkite sumą tarp grupių – bendra objekto suma išliks tokia pati.</small></div></div><div class="notice">${ic('refresh')}<div><strong>4. Atnaujinkite demo faktą</strong><small>„Duomenų šaltiniuose“ įkelkite pavyzdinį paketą ir stebėkite pasikeitusį faktą.</small></div></div>`)}
function changeRole(){role=$('#roleChoice').value;closeModal();render();toast('Demo vaidmuo pakeistas.')}
function showRole(){modal('Demo vaidmuo',`<p>Vaidmenų perjungimas demonstruoja skirtingus darbo scenarijus. Tai nėra tikras prisijungimas ar prieigos teisių sistema.</p><div class="formfield"><label for="roleChoice">Pasirinkite vaidmenį</label><select id="roleChoice"><option value="pv" ${role==='pv'?'selected':''}>Projekto vadovas · planavimas ir perskirstymai</option><option value="director" ${role==='director'?'selected':''}>Įmonės vadovas · finansų peržiūra</option></select></div>`,`<button class="primary" onclick="changeRole()">Taikyti</button>`)}
function showCategory(c){let p=project(),ds=invoices(p,month,c),s=stats(p);modal(cats[c],`<p>${esc(p.name)} · ${monthNames[month]}</p><div class="detailstats"><div><label>Grupės biudžetas</label>${eur(p.budgets[c])}</div><div><label>Likutis nuo pradžios</label><span class="${p.budgets[c]<cumulative(p,c)?'textred':''}">${eur(p.budgets[c]-cumulative(p,c))}</span></div><div><label>Mėnesio planas</label>${eur(p.plans[month].values[c])}</div><div><label>Mėnesio faktas · HANSA</label>${eur(actual(p,c))}</div></div><h3 style="font-size:.95rem;font-weight:600">Mėnesio faktinių sąnaudų detalizacija</h3><div class="tablewrap"><table><thead><tr><th>Sąnaudų pogrupis</th><th class="num">Faktas (€)</th></tr></thead><tbody>${subgroups[c].map(sub=>`<tr><td style="white-space:normal">${esc(sub)}</td><td class="num">${fmt(sum(ds.filter(d=>d.sub===sub).map(d=>d.amount)))}</td></tr>`).join('')}<tr class="total"><td>Iš viso</td><td class="num">${fmt(actual(p,c))}</td></tr></tbody></table></div>`,`<button class="primary" onclick="closeModal();tab='documents';doccat='${c}';filter='';render()">Peržiūrėti dokumentus</button>`)}
function showDocument(id){let d=db.docs.find(d=>d.id===id),p=db.projects.find(p=>p.id===d.project);modal('Sąnaudų dokumentas',`<div class="kv"><span>Dokumentas</span><strong>${esc(d.number)}</strong></div><div class="kv"><span>Data</span><strong>${d.date}</strong></div><div class="kv"><span>Tiekėjas / šaltinis</span><strong>${esc(d.supplier)}</strong></div><div class="kv"><span>Objektas</span><strong>${esc(p.code+' · '+p.name)}</strong></div><div class="kv"><span>Sąnaudų grupė</span><strong>${cats[d.category]}</strong></div><div class="kv"><span>Detalizacija</span><strong>${esc(d.sub)}</strong></div><div class="kv"><span>Suma be PVM</span><strong>${eur(d.amount)}</strong></div><div class="kv"><span>Duomenų šaltinis</span><strong>HANSA · pavyzdinis dokumentas</strong></div><p style="margin:18px 0 0">Faktinės sumos šioje aplikacijoje neredaguojamos.</p>`)}
function showTransfer(){if(!writable())return;let p=project();modal('Perskirstyti objekto biudžetą',`<p>Perkelkite biudžetą tarp sąnaudų grupių. Bendra objekto biudžeto suma <strong>${eur(sum(p.budgets))}</strong> nesikeičia.</p><div class="formgrid"><div class="formfield"><label for="tr-from">Iš sąnaudų grupės</label><select id="tr-from" onchange="transferPreview()">${cats.map((c,i)=>`<option value="${i}">${c}</option>`).join('')}</select></div><div class="formfield"><label for="tr-to">Į sąnaudų grupę</label><select id="tr-to" onchange="transferPreview()">${cats.map((c,i)=>`<option value="${i}" ${i===3?'selected':''}>${c}</option>`).join('')}</select></div><div class="formfield full"><label for="tr-amount">Perkeliama suma (€)</label><input id="tr-amount" type="number" min="0.01" step="0.01" placeholder="Pvz., 10 000" oninput="transferPreview()"></div><div class="formfield full"><label for="tr-reason">Perskirstymo priežastis</label><textarea id="tr-reason" placeholder="Pvz., darbai vietoje savo darbuotojų perduodami subrangovui." required></textarea></div></div><div id="transfer-preview" class="callout" style="margin:18px 0 0">Pasirinktos grupės laisvas likutis: ${eur(p.budgets[0]-cumulative(p,0))}</div>`,`<button class="primary" onclick="saveTransfer()">Patvirtinti perskirstymą</button>`)}
function transferPreview(){let p=project(),from=Number($('#tr-from').value),to=Number($('#tr-to').value),v=Number($('#tr-amount').value)||0;$('#transfer-preview').textContent=`Laisvas likutis: ${eur(p.budgets[from]-cumulative(p,from))}. Po perkėlimo: ${cats[from]} – ${eur(p.budgets[from]-v)}; ${cats[to]} – ${eur(p.budgets[to]+v)}.`}
function saveTransfer(){if(!writable())return;let p=project(),from=Number($('#tr-from').value),to=Number($('#tr-to').value),amount=round(Number($('#tr-amount').value)),reason=$('#tr-reason').value.trim();if(from===to)return error('Pasirinkite dvi skirtingas sąnaudų grupes.');if(!Number.isFinite(amount)||amount<=0)return error('Įveskite teigiamą perskirstymo sumą.');if(amount>round(p.budgets[from]-cumulative(p,from)))return error('Suma viršija grupės laisvą biudžeto likutį.');if(!reason)return error('Nurodykite perskirstymo priežastį.');let total=sum(p.budgets);p.budgets[from]=round(p.budgets[from]-amount);p.budgets[to]=round(p.budgets[to]+amount);if(sum(p.budgets)!==total)throw Error('Budget invariant');db.history.unshift({project:p.id,from,to,amount,reason,time:now()});persist();closeModal();render();toast('Biudžetas perskirstytas. Bendra suma nepasikeitė.')}
function now(){return new Date().toLocaleString('lt-LT',{timeZone:'Europe/Vilnius',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function editProject(id=null){if(!writable())return;let p=id?db.projects.find(p=>p.id===id):null;modal(p?'Objekto kortelė':'Naujas statybos objektas',`<form id="project-form"><div class="formgrid"><div class="formfield full"><label for="pr-name">Objekto pavadinimas</label><input id="pr-name" required value="${esc(p?.name||'')}"></div><div class="formfield"><label for="pr-code">Objekto kodas HANSA sistemoje</label><input id="pr-code" required value="${esc(p?.code||'VRS-')}"></div><div class="formfield"><label for="pr-city">Miestas</label><input id="pr-city" required value="${esc(p?.city||'')}"></div><div class="formfield"><label for="pr-manager">Projekto vadovas</label><input id="pr-manager" required value="${esc(p?.manager||'')}"></div><div class="formfield"><label for="pr-status">Būsena</label><select id="pr-status">${['Planuojamas','Vykdomas','Užbaigtas'].map(s=>`<option ${s===p?.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="formfield"><label for="pr-start">Pradžia</label><input id="pr-start" type="date" required value="${p?.start||'2026-11-26'}"></div><div class="formfield"><label for="pr-end">Sutarties pabaiga</label><input id="pr-end" type="date" required value="${p?.end||'2027-11-26'}"></div><div class="formfield full"><label for="pr-contract">Sutarties vertė be PVM (€)</label><input id="pr-contract" type="number" min="0" step="0.01" required value="${p?.contract||''}"></div></div></form>${p?`<div class="kv"><span>Bendras biudžetas</span><strong>${eur(sum(p.budgets))}</strong></div><div class="kv"><span>Sutarties likusių darbų vertė</span><strong>${eur(p.contract-p.baseRevenue-sum(months.filter(m=>m<=month).map(m=>p.revenues[m]||0)))}</strong></div>`:'<p style="margin-top:18px">Sukūrus objektą, galėsite suplanuoti jo biudžeto eilutes.</p>'}`,`<button class="primary" onclick="saveProject('${id||''}')">Išsaugoti</button>`)}
function saveProject(id){if(!writable())return;let form=$('#project-form');if(!form.reportValidity())return;let get=n=>$('#pr-'+n).value.trim(),code=get('code');if(db.projects.some(p=>p.code.toLowerCase()===code.toLowerCase()&&p.id!==id))return error('Objektas su tokiu kodu jau yra.');if(get('end')<get('start'))return error('Pabaigos data negali būti ankstesnė už pradžią.');let data={name:get('name'),code,city:get('city'),manager:get('manager'),status:get('status'),start:get('start'),end:get('end'),contract:round(Number(get('contract')))};if(!data.name||!data.city||!data.manager)return error('Užpildykite objekto pavadinimą, miestą ir projekto vadovą.');if(id){Object.assign(db.projects.find(p=>p.id===id),data);persist();closeModal();render();toast('Objekto kortelė išsaugota.')}else{let p={id:'p'+Date.now(),...data,budgets:cats.map(()=>0),initial:0,base:cats.map(()=>0),baseRevenue:0,plans:Object.fromEntries(months.map(m=>[m,{values:cats.map(()=>0),revenue:0,note:''}])),openingStocks:[0,0],stocks:Object.fromEntries(months.map(m=>[m,[0,0]])),advance:0,revenues:{},paidAdvances:{}};db.projects.push(p);pid=p.id;persist();closeModal();view='object';tab='control';render();showBudget()}}
function showBudget(){if(!writable())return;let p=project(),locked=p.status!=='Planuojamas'&&p.initial>0;modal('Objekto biudžeto planas',`<p>${esc(p.name)}. ${locked?'Vykdomo objekto bendras biudžetas užfiksuotas. Lėšos tarp grupių keičiamos perskirstymu.':'Suplanuokite bendrą objekto biudžetą pagal sąnaudų grupes.'}</p>${!locked?`<div class="inlineactions" style="margin-bottom:14px"><button onclick="downloadTemplate()">${ic('download')}CSV šablonas</button><button onclick="$('#budget-file').click()">${ic('up')}Importuoti CSV</button><input type="file" id="budget-file" accept=".csv,text/csv" style="display:none" onchange="readBudgetFile(this.files[0])"></div>`:''}<div class="tablewrap"><table><thead><tr><th>Sąnaudų grupė</th><th class="num">Biudžetas (€)</th></tr></thead><tbody>${cats.map((c,i)=>`<tr><td>${c}</td><td class="num"><input class="editcell" id="budget-${i}" aria-label="${c} bendras biudžetas" type="number" min="0" step="0.01" value="${p.budgets[i]}" ${locked?'disabled':''} oninput="budgetPreview()"></td></tr>`).join('')}<tr class="total"><td>Iš viso</td><td class="num" id="budget-total">${eur(sum(p.budgets))}</td></tr></tbody></table></div>`,locked?`<button class="primary" onclick="closeModal();showTransfer()">Perskirstyti biudžetą</button>`:`<button class="primary" onclick="saveBudget()">Išsaugoti biudžetą</button>`)}
function budgetPreview(){$('#budget-total').textContent=eur(sum(cats.map((_,i)=>Number($('#budget-'+i).value)||0)))}
function saveBudget(){if(!writable())return;let p=project();if(p.status!=='Planuojamas'&&p.initial>0)return error('Šio objekto biudžetas užfiksuotas. Naudokite perskirstymą.');let vals=cats.map((_,i)=>Number($('#budget-'+i).value));if(vals.some((v,i)=>!Number.isFinite(v)||v<0||$('#budget-'+i).value===''))return error('Kiekvienai grupei įveskite neneigiamą sumą.');if(sum(vals)<=0)return error('Bendras biudžetas turi būti didesnis už nulį.');p.budgets=vals.map(round);p.initial=sum(vals);persist();closeModal();render();toast('Objekto biudžetas išsaugotas.')}
async function readBudgetFile(file){if(!file)return;let txt=(await file.text()).replace(/^\uFEFF/,''),rows=txt.trim().split(/\r?\n/),result=new Map();try{rows.slice(1).forEach(line=>{let parts=line.split(';').map(x=>x.trim().replace(/^"|"$/g,'')),i=cats.findIndex(c=>c.toLowerCase()===parts[0]?.toLowerCase()),v=Number((parts[1]||'').replace(/\s/g,'').replace(',','.'));if(i<0||parts.length!==2||!Number.isFinite(v)||v<0||parts[1]===''||result.has(i))throw Error();result.set(i,round(v))});if(result.size!==7)throw Error();result.forEach((v,i)=>$('#budget-'+i).value=v);budgetPreview();toast('Biudžeto eilutės įkeltos peržiūrai. Išsaugokite biudžetą.')}catch{error('CSV turi turėti antraštę ir 7 unikalias eilutes: Sąnaudų grupė;Biudžetas. Naudokite pateiktą šabloną.')}}
function sampleBatch(){let p=db.projects[0];return [{id:'sync-001',project:p.id,date:'2026-11-25',number:'SF-DEMO-101',supplier:'Medžiagų tiekėjas',category:1,sub:subgroups[1][0],amount:4500,source:'HANSA'},{id:'sync-002',project:p.id,date:'2026-11-25',number:'SF-DEMO-102',supplier:'Subrangovas A',category:3,sub:subgroups[3][0],amount:6250,source:'HANSA'},{id:'sync-003',project:p.id,date:'2026-11-25',number:'SF-DEMO-103',supplier:'Mechanizmų nuoma',category:2,sub:subgroups[2][0],amount:380,source:'HANSA'}]}
function showSync(){let batch=sampleBatch().filter(d=>!db.docs.some(x=>x.id===d.id));modal('Atnaujinti demo duomenis',`<p>${batch.length?'Šis pavyzdinis paketas papildys lapkričio faktines sąnaudas.':'Visi šio demo paketo dokumentai jau įkelti. Pakartotinai jie nebus dubliuojami.'} Ryšys su tikra HANSA sistema nesukurtas.</p><div class="tablewrap"><table><thead><tr><th>Dokumentas / grupė</th><th class="num">Suma (€)</th></tr></thead><tbody>${batch.map(d=>`<tr><td>${d.number}<div class="rownote" style="margin-left:0">${cats[d.category]}</div></td><td class="num">${fmt(d.amount)}</td></tr>`).join('')||'<tr><td colspan="2" class="empty">Naujų dokumentų nėra.</td></tr>'}</tbody></table></div><p style="margin-top:16px">Objektas: ${esc(db.projects[0].code+' · '+db.projects[0].name)}</p>`,batch.length?`<button class="primary" onclick="applySync()">Įkelti ${batch.length} dokumentus</button>`:'')}
function applySync(){let batch=sampleBatch().filter(d=>!db.docs.some(x=>x.id===d.id));if(!batch.length)return;db.docs.push(...batch);db.sync=now();db.logs.unshift({time:db.sync,count:batch.length});persist();closeModal();render();toast('Įkelti '+batch.length+' pavyzdiniai dokumentai. Faktinės sumos atnaujintos.')}
function resetDemo(){modal('Atkurti pradinius demo duomenis',`<p>Bus pašalinti šioje naršyklėje atlikti plano pakeitimai, nauji objektai ir perskirstymai. Pradiniai pavyzdžiai bus atkurti.</p>`,`<button class="primary" onclick="db=seed();persist();pid='p1';closeModal();render();toast('Pradiniai demo duomenys atkurti.')">Atkurti duomenis</button>`)}
function csv(filename,rows){let txt='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV failas paruoštas.')}
const dec=n=>round(n).toFixed(2).replace('.',',');
function exportBudget(){let p=project();csv(p.code+'_biudzetas_'+month+'.csv',[['Sąnaudų grupė','Biudžetas','Mėnesio faktas','Faktas nuo pradžios','Likutis'],...cats.map((c,i)=>[c,dec(p.budgets[i]),dec(actual(p,i)),dec(cumulative(p,i)),dec(p.budgets[i]-cumulative(p,i))])])}
function exportDocs(){let p=project();csv(p.code+'_dokumentai_'+month+'.csv',[['Data','Dokumentas','Tiekėjas','Kategorija','Detalizacija','Suma be PVM'],...invoices(p).filter(d=>(doccat==='all'||d.category===Number(doccat))&&[d.supplier,d.number,d.sub].some(v=>v.toLowerCase().includes(filter.toLowerCase()))).map(d=>[d.date,d.number,d.supplier,cats[d.category],d.sub,dec(d.amount)])])}
function exportMonthly(){let p=project(),s=stats(p),pl=p.plans[month];csv(p.code+'_menesio_ataskaita_'+month+'.csv',[['Rodiklis','Planas','Faktas'],['Aktavimo suma',dec(pl.revenue),dec(p.revenues[month]||0)],['Visos sąnaudos',dec(s.pl),dec(s.f)],['Mėnesio rezultatas',dec(pl.revenue-s.pl),dec((p.revenues[month]||0)-s.f)],...cats.map((c,i)=>[c,dec(pl.values[i]),dec(actual(p,i))]),['Medžiagų likučiai','',dec(stocks(p)[0])],['Mažaverčio likučiai','',dec(stocks(p)[1])],['Avansų nepadengtas likutis','',dec(p.advance)],['Per mėnesį išmokėti avansai','',dec(p.paidAdvances[month]||0)]])}
function downloadTemplate(){csv('Versina_biudzeto_sablonas.csv',[['Sąnaudų grupė','Biudžetas'],...cats.map(c=>[c,'0,00'])])}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});

function allocate(total,parts){let old=sum(parts);if(!old)return parts.map((_,i)=>i===0?total:0);let out=parts.map(v=>round(v/old*total));out[out.length-1]=round(out[out.length-1]+total-sum(out));return out}
function planParts(p,c){let saved=p.plans[month].details?.[c];if(saved&&Math.abs(sum(saved)-p.plans[month].values[c])<.01)return saved;let weights=subgroups[c].map((_,i)=>c===0?(i===0?.6:.4):i===0?1:0);return allocate(p.plans[month].values[c],weights)}
function showPlanDetails(c,saveDraft=false){if(!writable())return;if(saveDraft){let inputs=[...document.querySelectorAll('[id^="plan-"][type="number"]')];if(inputs.some(i=>!i.checkValidity()||i.value===''))return toast('Pirmiausia patikrinkite plano sumas.');savePlan()}let p=project(),parts=planParts(p,c);modal('Mėnesio plano pogrupiai',`<p>${cats[c]} · ${monthNames[month]} · ${esc(p.name)}</p><div class="formgrid">${subgroups[c].map((sub,i)=>`<div class="formfield full"><label for="part-${i}">${esc(sub)} (€)</label><input id="part-${i}" type="number" min="0" step="0.01" value="${parts[i]}" oninput="partsPreview(${c})"></div>`).join('')}</div><div class="kv"><span>Bendras grupės mėnesio planas</span><strong id="parts-total">${eur(sum(parts))}</strong></div>`,`<button class="primary" onclick="savePlanDetails(${c})">Išsaugoti pogrupius</button>`)}
function partsPreview(c){$('#parts-total').textContent=eur(sum(subgroups[c].map((_,i)=>Number($('#part-'+i).value)||0)))}
function savePlanDetails(c){if(!writable())return;let vals=subgroups[c].map((_,i)=>Number($('#part-'+i).value));if(vals.some((v,i)=>!Number.isFinite(v)||v<0||$('#part-'+i).value===''))return error('Įveskite neneigiamas pogrupių sumas.');let pl=project().plans[month];pl.details ||= [];pl.details[c]=vals.map(round);pl.values[c]=sum(vals);persist();closeModal();render();toast('Mėnesio plano pogrupiai išsaugoti.')}
render();
